#define _CRT_SECURE_NO_WARNINGS
#include <windows.h>
#include <gdiplus.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <wchar.h>

typedef struct { uint8_t *p; size_t n,c; } Buf;
typedef struct Node Node;
struct Node { int k; uint8_t a,b; uint16_t parts,sw,sh,dw,dh; uint32_t x,y,r,bt,z,t; uint16_t flags; uint8_t bpp,pt; uint16_t iw,ih; char png[512]; Node *v; int n,c; };
typedef struct { char path[512]; Node root; } File;
typedef struct { File *v; int n,c; } Files;
typedef struct liq_attr liq_attr; typedef struct liq_image liq_image; typedef struct liq_result liq_result;
typedef struct { uint8_t r,g,b,a; } liq_color; typedef struct { uint32_t count; liq_color entries[256]; } liq_palette;
typedef struct { HMODULE h; liq_attr* (__cdecl *ac)(void); void (__cdecl *ad)(liq_attr*); int (__cdecl *sm)(liq_attr*,int); liq_image* (__cdecl *ic)(liq_attr*,void*,int,int,double); void (__cdecl *id)(liq_image*); int (__cdecl *q)(liq_attr*,liq_image*,liq_result**); const liq_palette* (__cdecl *gp)(liq_result*); int (__cdecl *wd)(liq_result*,float); int (__cdecl *wr)(liq_result*,liq_image*,void*,size_t); void (__cdecl *rd)(liq_result*); } Liq;
static Liq liq; static int liq_ok=-1; static ULONG_PTR gdip;
static void die(const char *s){fprintf(stderr,"%s\n",s);exit(1);} static void *mem(size_t n){void*p=malloc(n?n:1);if(!p)die("out of memory");return p;}
static void *grow(void*p,size_t n){p=realloc(p,n?n:1);if(!p)die("out of memory");return p;} static void put(Buf*b,const void*p,size_t n){if(b->n+n>b->c){b->c=b->c?b->c*2:4096;while(b->c<b->n+n)b->c*=2;b->p=grow(b->p,b->c);}memcpy(b->p+b->n,p,n);b->n+=n;} static void put8(Buf*b,uint8_t v){put(b,&v,1);} static void text(Buf*b,const char*s){put(b,s,strlen(s));}
static uint16_t rd16(const uint8_t*p){return p[0]|p[1]<<8;} static uint32_t rd32(const uint8_t*p){return p[0]|p[1]<<8|p[2]<<16|p[3]<<24;} static void wr16(uint8_t*p,uint16_t v){p[0]=v;p[1]=v>>8;} static void wr32(uint8_t*p,uint32_t v){p[0]=v;p[1]=v>>8;p[2]=v>>16;p[3]=v>>24;}
static uint8_t *load(const wchar_t*p,size_t*n){FILE*f=_wfopen(p,L"rb");long z;if(!f)die("cannot open file");fseek(f,0,SEEK_END);z=ftell(f);fseek(f,0,SEEK_SET);if(z<0)die("bad file");uint8_t*b=mem(z);if(fread(b,1,z,f)!=(size_t)z)die("cannot read file");fclose(f);*n=z;return b;} static void save(const wchar_t*p,const void*b,size_t n){FILE*f=_wfopen(p,L"wb");if(!f)die("cannot create file");if(n&&fwrite(b,1,n,f)!=n)die("cannot write file");fclose(f);}
static void join(wchar_t*out,const wchar_t*a,const wchar_t*b){swprintf(out,L"%ls\\%ls",a,b);} static void mkdirs(const wchar_t*p){wchar_t q[2048];wcsncpy(q,p,2047);q[2047]=0;for(wchar_t*s=q+3;*s;s++)if(*s==L'\\'){*s=0;CreateDirectoryW(q,0);*s=L'\\';}CreateDirectoryW(q,0);} static void parentdir(const wchar_t*p){wchar_t q[2048];wcsncpy(q,p,2047);q[2047]=0;wchar_t*s=wcsrchr(q,L'\\');if(s){*s=0;mkdirs(q);}}
static Node *add(Node*p){if(p->n==p->c){p->c=p->c?p->c*2:4;p->v=grow(p->v,p->c*sizeof(Node));}Node*x=&p->v[p->n++];memset(x,0,sizeof(*x));return x;}
static int pacok(const uint8_t*d,size_t n,size_t o){return o+36<=n&&(d[o]==0||d[o]==2)&&(d[o+1]>=1&&d[o+1]<=3)&&rd32(d+o+28)>=36&&rd32(d+o+28)<=n-o;}
static int giqok(const uint8_t*d,size_t n,size_t o){if(o+16>n)return 0;uint8_t b=d[o+2],p=d[o+3];uint16_t w=rd16(d+o+4),h=rd16(d+o+6);return b==3&&p==3&&w&&h&&o+1040+(size_t)w*h<=n;}
static void parse(Node*p,const uint8_t*d,size_t n,size_t o){p->k=0;p->a=d[o];p->b=d[o+1];p->parts=rd16(d+o+2);p->sw=rd16(d+o+4);p->sh=rd16(d+o+6);p->dw=rd16(d+o+8);p->dh=rd16(d+o+10);p->x=rd32(d+o+12);p->y=rd32(d+o+16);p->r=rd32(d+o+20);p->bt=rd32(d+o+24);p->z=rd32(d+o+28);p->t=rd32(d+o+32);size_t q=o+36,e=o+p->z;while(q<e){Node*x=add(p);if(pacok(d,e,q)){parse(x,d,e,q);q+=x->z;}else if(giqok(d,e,q)){x->k=1;x->flags=rd16(d+q);x->bpp=d[q+2];x->pt=d[q+3];x->iw=rd16(d+q+4);x->ih=rd16(d+q+6);x->x=(uint32_t)q;x->z=1040+(uint32_t)x->iw*x->ih;q+=x->z;}else die("bad PAC layout");}}
static void unsw(uint8_t*out,const uint8_t*in,int row,int h){size_t s=0;for(int by=0;by<h/8;by++)for(int bx=0;bx<row/16;bx++)for(int y=0;y<8;y++){memcpy(out+(by*8+y)*row+bx*16,in+s,16);s+=16;}} static void sw(uint8_t*out,const uint8_t*in,int row,int h){size_t d=0;for(int by=0;by<h/8;by++)for(int bx=0;bx<row/16;bx++)for(int y=0;y<8;y++){memcpy(out+d,in+(by*8+y)*row+bx*16,16);d+=16;}}
static void gdinit(void){if(gdip)return;GdiplusStartupInput x;memset(&x,0,sizeof(x));x.GdiplusVersion=1;if(GdiplusStartup(&gdip,&x,0)!=Ok)die("GDI+ failed");}
static CLSID pngcls(void){UINT n,z;CLSID c={0};if(GdipGetImageEncodersSize(&n,&z)!=Ok)die("PNG encoder failed");ImageCodecInfo*i=mem(z);GdipGetImageEncoders(n,z,i);for(UINT k=0;k<n;k++)if(i[k].MimeType&&!wcscmp(i[k].MimeType,L"image/png")){c=i[k].Clsid;break;}free(i);return c;}
static void pngsave(const wchar_t*p,const uint8_t*rgba,int w,int h){gdinit();parentdir(p);uint8_t*a=mem((size_t)w*h*4);for(size_t i=0;i<(size_t)w*h;i++){a[i*4]=rgba[i*4+2];a[i*4+1]=rgba[i*4+1];a[i*4+2]=rgba[i*4];a[i*4+3]=rgba[i*4+3];}GpBitmap*b=0;CLSID c=pngcls();GpStatus s=GdipCreateBitmapFromScan0(w,h,w*4,PixelFormat32bppARGB,a,&b);if(s!=Ok){printf("bitmap %d\n",s);die("cannot save PNG");}s=GdipSaveImageToFile((GpImage*)b,p,&c,0);if(s!=Ok){printf("png %d\n",s);die("cannot save PNG");}GdipDisposeImage((GpImage*)b);free(a);}
static uint8_t *pngload(const wchar_t*p,UINT*w,UINT*h){gdinit();GpImage*i=0;if(GdipLoadImageFromFile(p,&i)!=Ok)die("cannot load PNG");GdipGetImageWidth(i,w);GdipGetImageHeight(i,h);GpRect r={0,0,(INT)*w,(INT)*h};BitmapData d;if(GdipBitmapLockBits((GpBitmap*)i,&r,ImageLockModeRead,PixelFormat32bppARGB,&d)!=Ok)die("cannot read PNG");uint8_t*b=mem((size_t)*w**h*4);for(UINT y=0;y<*h;y++){uint8_t*s=(uint8_t*)d.Scan0+(ptrdiff_t)y*d.Stride;for(UINT x=0;x<*w;x++){uint8_t*q=s+x*4,*v=b+((size_t)y**w+x)*4;v[0]=q[2];v[1]=q[1];v[2]=q[0];v[3]=q[3];}}GdipBitmapUnlockBits((GpBitmap*)i,&d);GdipDisposeImage(i);return b;}
static FARPROC fp(HMODULE h,const char*n){FARPROC p=GetProcAddress(h,n);if(!p)die("bad libimagequant.dll");return p;} static int liqinit(void){if(liq_ok>=0)return liq_ok;memset(&liq,0,sizeof(liq));liq.h=LoadLibraryW(L"libimagequant.dll");if(!liq.h)return liq_ok=0;liq.ac=(void*)fp(liq.h,"liq_attr_create");liq.ad=(void*)fp(liq.h,"liq_attr_destroy");liq.sm=(void*)fp(liq.h,"liq_set_max_colors");liq.ic=(void*)fp(liq.h,"liq_image_create_rgba");liq.id=(void*)fp(liq.h,"liq_image_destroy");liq.q=(void*)fp(liq.h,"liq_quantize_image");liq.gp=(void*)fp(liq.h,"liq_get_palette");liq.wd=(void*)fp(liq.h,"liq_set_dithering_level");liq.wr=(void*)fp(liq.h,"liq_write_remapped_image");liq.rd=(void*)fp(liq.h,"liq_result_destroy");return liq_ok=1;}
static int quant(const uint8_t*r,int w,int h,uint8_t*ix,uint8_t*pal){if(!liqinit())return 0;liq_attr*a=liq.ac();liq_image*i=liq.ic(a,(void*)r,w,h,0);liq_result*z=0;if(!a||!i||liq.sm(a,256)||liq.q(a,i,&z))return 0;liq.wd(z,0);if(liq.wr(z,i,ix,(size_t)w*h))return 0;memset(pal,0,1024);const liq_palette*p=liq.gp(z);for(uint32_t k=0;k<p->count;k++){pal[k*4]=p->entries[k].r;pal[k*4+1]=p->entries[k].g;pal[k*4+2]=p->entries[k].b;pal[k*4+3]=p->entries[k].a;}liq.rd(z);liq.id(i);liq.ad(a);return 1;}
static void palette(const uint8_t*r,int w,int h,uint8_t*ix,uint8_t*pal){int n=0;for(size_t i=0;i<(size_t)w*h;i++){int k;for(k=0;k<n;k++)if(!memcmp(pal+k*4,r+i*4,4))break;if(k==n){if(n==256){if(!quant(r,w,h,ix,pal))die("more than 256 colors and libimagequant.dll is unavailable");printf("quantized\n");return;}memcpy(pal+n++*4,r+i*4,4);}ix[i]=(uint8_t)k;}}
static void emitnode(Buf*b,Node*n,int dep){char s[1200];for(int i=0;i<dep;i++)text(b,"  ");if(!n->k){sprintf(s,"<pac a=\"%u\" b=\"%u\" parts=\"%u\" sw=\"%u\" sh=\"%u\" dw=\"%u\" dh=\"%u\" x=\"%u\" y=\"%u\" r=\"%u\" bt=\"%u\" t=\"%u\">\n",n->a,n->b,n->parts,n->sw,n->sh,n->dw,n->dh,n->x,n->y,n->r,n->bt,n->t);text(b,s);for(int i=0;i<n->n;i++)emitnode(b,n->v+i,dep+1);for(int i=0;i<dep;i++)text(b,"  ");text(b,"</pac>\n");}else{sprintf(s,"<image flags=\"%u\" bpp=\"%u\" pt=\"%u\" w=\"%u\" h=\"%u\" file=\"%s\"/>\n",n->flags,n->bpp,n->pt,n->iw,n->ih,n->png);text(b,s);}}
static void extractnode(Node*n,const uint8_t*d,const wchar_t*out,const char*base,int*id){if(n->k){char rel[600];sprintf(rel,"%s.%02d.png",base,(*id)++);strcpy(n->png,rel);size_t o=n->x;const uint8_t*pal=d+o+16;const uint8_t*src=d+o+1040;size_t z=(size_t)n->iw*n->ih;uint8_t*idx=mem(z),*rgba=mem(z*4);unsw(idx,src,n->iw,n->ih);for(size_t i=0;i<z;i++)memcpy(rgba+i*4,pal+idx[i]*4,4);wchar_t wrel[1024],p[2048];MultiByteToWideChar(CP_UTF8,0,rel,-1,wrel,1024);for(wchar_t*q=wrel;*q;q++)if(*q==L'/')*q=L'\\';join(p,out,wrel);pngsave(p,rgba,n->iw,n->ih);free(idx);free(rgba);}else for(int i=0;i<n->n;i++)extractnode(n->v+i,d,out,base,id);}
static void addfile(Files*f,File*x){if(f->n==f->c){f->c=f->c?f->c*2:256;f->v=grow(f->v,f->c*sizeof(File));}f->v[f->n++]=*x;}
static void walkextract(const wchar_t*root,const wchar_t*dir,const wchar_t*out,const wchar_t*rel,Files*fs){wchar_t pat[2048];swprintf(pat,L"%ls\\*",dir);WIN32_FIND_DATAW fd;HANDLE h=FindFirstFileW(pat,&fd);if(h==INVALID_HANDLE_VALUE)return;do{if(!wcscmp(fd.cFileName,L".")||!wcscmp(fd.cFileName,L".."))continue;wchar_t full[2048],nr[2048];join(full,dir,fd.cFileName);if(*rel)swprintf(nr,L"%ls\\%ls",rel,fd.cFileName);else wcsncpy(nr,fd.cFileName,2047);if(fd.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY)walkextract(root,full,out,nr,fs);else{wchar_t*e=wcsrchr(fd.cFileName,L'.');if(!e||_wcsicmp(e,L".pac"))continue;size_t z;uint8_t*d=load(full,&z);if(!pacok(d,z,0)||rd32(d+28)!=z)die("invalid PAC");File x;memset(&x,0,sizeof(x));WideCharToMultiByte(CP_UTF8,0,nr,-1,x.path,512,0,0);for(char*p=x.path;*p;p++)if(*p=='\\')*p='/';parse(&x.root,d,z,0);char base[512];strcpy(base,x.path);char*q=strrchr(base,'.');if(q)*q=0;int id=0;extractnode(&x.root,d,out,base,&id);addfile(fs,&x);free(d);}}while(FindNextFileW(h,&fd));FindClose(h);}
static const char *av(const char*s,const char*n,char*b){char p[64];sprintf(p,"%s=\"",n);s=strstr(s,p);if(!s)return 0;s+=strlen(p);const char*e=strchr(s,'\"');if(!e)return 0;size_t z=e-s;if(z>511)z=511;memcpy(b,s,z);b[z]=0;return b;} static unsigned au(const char*s,const char*n){char b[512];const char*x=av(s,n,b);return x?(unsigned)strtoul(x,0,10):0;}
static Node readnode(char **pp){char*b=*pp;Node n;memset(&n,0,sizeof(n));if(!strncmp(b,"<image",6)){char*e=strstr(b,"/>");if(!e)die("bad xml");n.k=1;n.flags=au(b,"flags");n.bpp=au(b,"bpp");n.pt=au(b,"pt");n.iw=au(b,"w");n.ih=au(b,"h");char t[512];if(!av(b,"file",t))die("bad xml");strcpy(n.png,t);*pp=e+2;return n;}if(strncmp(b,"<pac",4))die("bad xml");char*e=strchr(b,'>');if(!e)die("bad xml");n.a=au(b,"a");n.b=au(b,"b");n.parts=au(b,"parts");n.sw=au(b,"sw");n.sh=au(b,"sh");n.dw=au(b,"dw");n.dh=au(b,"dh");n.x=au(b,"x");n.y=au(b,"y");n.r=au(b,"r");n.bt=au(b,"bt");n.t=au(b,"t");b=e+1;while(1){while(*b&&(*b==' '||*b=='\n'||*b=='\r'||*b=='\t'))b++;if(!strncmp(b,"</pac>",6)){*pp=b+6;break;}Node*x=add(&n);*x=readnode(&b);}return n;}
static void packnode(Buf*out,Node*n,const wchar_t*in){if(n->k){wchar_t r[1024],p[2048];MultiByteToWideChar(CP_UTF8,0,n->png,-1,r,1024);join(p,in,r);UINT w,h;uint8_t*rgba=pngload(p,&w,&h);if(w!=n->iw||h!=n->ih)die("PNG size changed");size_t z=(size_t)w*h;uint8_t*ix=mem(z),pal[1024],*raw=mem(z);memset(pal,0,1024);palette(rgba,w,h,ix,pal);uint8_t hdr[1040];memset(hdr,0,sizeof(hdr));wr16(hdr,n->flags);hdr[2]=n->bpp;hdr[3]=n->pt;wr16(hdr+4,w);wr16(hdr+6,h);wr32(hdr+8,16);wr32(hdr+12,1040);memcpy(hdr+16,pal,1024);put(out,hdr,1040);sw(raw,ix,w,h);put(out,raw,z);free(raw);free(ix);free(rgba);return;}size_t start=out->n;uint8_t hdr[36];memset(hdr,0,sizeof(hdr));hdr[0]=n->a;hdr[1]=n->b;wr16(hdr+2,n->parts);wr16(hdr+4,n->sw);wr16(hdr+6,n->sh);wr16(hdr+8,n->dw);wr16(hdr+10,n->dh);wr32(hdr+12,n->x);wr32(hdr+16,n->y);wr32(hdr+20,n->r);wr32(hdr+24,n->bt);wr32(hdr+32,n->t);put(out,hdr,36);for(int i=0;i<n->n;i++)packnode(out,n->v+i,in);wr32(out->p+start+28,(uint32_t)(out->n-start));}
static void importall(const wchar_t*in,const wchar_t*out){wchar_t xp[2048];join(xp,in,L"pac.xml");size_t z;uint8_t*raw=load(xp,&z);char*t=mem(z+1);memcpy(t,raw,z);t[z]=0;free(raw);char*p=t;while((p=strstr(p,"<file "))){char path[512],tmp[512];if(!av(p,"path",path))die("bad xml");char*e=strchr(p,'>');char*q=strstr(e,"<pac");Node n=readnode(&q);Buf b={0};packnode(&b,&n,in);wchar_t wr[1024],dst[2048];MultiByteToWideChar(CP_UTF8,0,path,-1,wr,1024);for(wchar_t*s=wr;*s;s++)if(*s==L'/')*s=L'\\';join(dst,out,wr);parentdir(dst);save(dst,b.p,b.n);free(b.p);p=q;}free(t);}
static int run(int ac,wchar_t**av){if(ac!=4||(wcscmp(av[1],L"e")&&wcscmp(av[1],L"i"))){fwprintf(stderr,L"PAC e input_dir output_dir\nPAC i input_dir output_dir\n");return 1;}if(!wcscmp(av[1],L"i")){mkdirs(av[3]);importall(av[2],av[3]);return 0;}Files fs={0};mkdirs(av[3]);walkextract(av[2],av[2],av[3],L"",&fs);Buf x={0};text(&x,"<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<pacs>\n");for(int i=0;i<fs.n;i++){char s[600];sprintf(s,"  <file path=\"%s\">\n",fs.v[i].path);text(&x,s);emitnode(&x,&fs.v[i].root,2);text(&x,"  </file>\n");}text(&x,"</pacs>\n");wchar_t xp[2048];join(xp,av[3],L"pac.xml");save(xp,x.p,x.n);free(x.p);printf("%d PAC files\n",fs.n);return 0;}
int main(void){int ac;wchar_t**av=CommandLineToArgvW(GetCommandLineW(),&ac);if(!av)return 1;int r=run(ac,av);LocalFree(av);return r;}
